<?php declare(strict_types=1); namespace Annam;
$title=$key==='pages'?'Pages':$spec['title'];$singular=['slots'=>'meal time','banners'=>'banner','pages'=>'page','zones'=>'delivery area'][$key]??'record';$subtitle=count($records).' '.($key==='slots'?'meal times':strtolower($title));$actions='<a class="o-btn o-btn-primary" href="/manage/'.e($key).'/new/"><svg class="o-ic"><use href="#o-plus"/></svg>Add '.e($singular).'</a>';
?>
<?php if($key!=='slots'): ?><form class="o-tools" method="get"><label class="o-search"><svg class="o-ic"><use href="#o-search"/></svg><input type="search" name="q" value="<?= e($query??'') ?>" placeholder="Search <?= e(strtolower($title)) ?>…" aria-label="Search <?= e(strtolower($title)) ?>"></label><noscript><button class="o-btn">Search</button></noscript></form><?php endif; ?>
<?php if($records): ?><div class="o-table-wrap"><table class="o-table"><thead><tr><?php if($key==='banners'): ?><th></th><?php endif; ?><th><?= ['slots'=>'Meal','zones'=>'Area','banners'=>'Title','pages'=>'Title'][$key]??'Name' ?></th><?php if($key==='zones'): ?><th>Pincode</th><th>Fee</th><th>Minimum</th><?php elseif($key==='slots'): ?><th>Orders close</th><th>Delivery</th><?php elseif($key==='pages'): ?><th>Address</th><th>In menu</th><?php elseif($key==='banners'): ?><th>Link</th><?php endif; ?><th><?= ['slots'=>'Active','zones'=>'Delivering','pages'=>'Published','banners'=>'Showing'][$key]??'Visible' ?></th><th><span class="o-sr">Actions</span></th></tr></thead><tbody><?php foreach($records as $row):$name=$row['name']??$row['title']??$row['area_name']??$row['label']??'';$active=$row[$key==='pages'?'published':'active'];$edit='/manage/'.$key.'/'.$row['id'].'/'; ?><tr><?php if($key==='banners'): ?><td><a class="o-thumb" href="<?= e($edit) ?>"><?php if($row['image']): ?><img src="<?= e(image_url($row['image'])) ?>" alt=""><?php else: ?><svg class="o-ic"><use href="#o-image"/></svg><?php endif; ?></a></td><?php endif; ?><td><a class="o-row-title" href="<?= e($edit) ?>"><?= e($name) ?></a></td><?php if($key==='zones'): ?><td><?= e($row['pincode']) ?></td><td class="o-money"><?= money($row['delivery_fee']) ?></td><td class="o-money"><?= money($row['min_order']) ?></td><?php elseif($key==='slots'): ?><td><?= e(date('g:i A',strtotime($row['order_cutoff']))) ?></td><td><?= $row['delivery_from']&&$row['delivery_to']?e(substr($row['delivery_from'],0,5).'–'.substr($row['delivery_to'],0,5)):'—' ?></td><?php elseif($key==='pages'): ?><td>/p/<?= e($row['slug']) ?>/</td><td><?= $row['show_in_nav']?'Yes':'No' ?></td><?php elseif($key==='banners'): ?><td><?= e($row['link']) ?></td><?php endif; ?><td><form method="post" action="<?= e($edit) ?>toggle/"><?= csrf() ?><button class="o-switch <?= $active?'is-on':'' ?>" type="submit" role="switch" aria-checked="<?= $active?'true':'false' ?>" aria-label="<?= e('Toggle '.$name) ?>"><i></i></button></form></td><td><div class="o-row-actions"><a class="o-icon-btn" href="<?= e($edit) ?>" aria-label="<?= e('Edit '.$name) ?>"><svg class="o-ic"><use href="#o-edit"/></svg></a><form method="post" action="<?= e($edit) ?>archive/" data-confirm="Remove this item from sale? Existing orders are preserved."><?= csrf() ?><button class="o-icon-btn" aria-label="<?= e('Remove '.$name) ?>"><svg class="o-ic"><use href="#o-trash"/></svg></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="o-empty"><svg class="o-ic"><use href="#o-search"/></svg><p>No matching <?= e(strtolower($title)) ?>.</p><a class="o-btn o-btn-primary" href="/manage/<?= e($key) ?>/new/">Add <?= e($singular) ?></a></div><?php endif; ?>
